  hacer: { present: ["hago", "hacés", "haces", "hace", "hacemos", "hacen"], preterite: ["hice", "hiciste", "hiciste", "hizo", "hicimos", "hicieron"], futureStem: "har", subjunctive: ["haga", "hagás", "hagas", "haga", "hagamos", "hagan"] },
  ir: { present: ["voy", "vas", "vas", "va", "vamos", "van"], preterite: ["fui", "fuiste", "fuiste", "fue", "fuimos", "fueron"], imperfect: ["iba", "ibas", "ibas", "iba", "íbamos", "iban"], future: ["iré", "irás", "irás", "irá", "iremos", "irán"], conditional: ["iría", "irías", "irías", "iría", "iríamos", "irían"], subjunctive: ["vaya", "vayás", "vayas", "vaya", "vayamos", "vayan"] },
  poder: { present: ["puedo", "podés", "puedes", "puede", "podemos", "pueden"], preterite: ["pude", "pudiste", "pudiste", "pudo", "pudimos", "pudieron"], futureStem: "podr", subjunctive: ["pueda", "podás", "puedas", "pueda", "podamos", "puedan"] },
  querer: { present: ["quiero", "querés", "quieres", "quiere", "queremos", "quieren"], preterite: ["quise", "quisiste", "quisiste", "quiso", "quisimos", "quisieron"], futureStem: "querr", subjunctive: ["quiera", "querás", "quieras", "quiera", "queramos", "quieran"] },
  decir: { present: ["digo", "decís", "dices", "dice", "decimos", "dicen"], preterite: ["dije", "dijiste", "dijiste", "dijo", "dijimos", "dijeron"], futureStem: "dir", subjunctive: ["diga", "digás", "digas", "diga", "digamos", "digan"] },
  venir: { present: ["vengo", "venís", "vienes", "viene", "venimos", "vienen"], preterite: ["vine", "viniste", "viniste", "vino", "vinimos", "vinieron"], futureStem: "vendr", subjunctive: ["venga", "vengás", "vengas", "venga", "vengamos", "vengan"] },
  saber: { present: ["sé", "sabés", "sabes", "sabe", "sabemos", "saben"], preterite: ["supe", "supiste", "supiste", "supo", "supimos", "supieron"], future: ["sabré", "sabrás", "sabrás", "sabrá", "sabremos", "sabrán"], conditional: ["sabría", "sabrías", "sabrías", "sabría", "sabríamos", "sabrían"], subjunctive: ["sepa", "sepás", "sepas", "sepa", "sepamos", "sepan"] },
  conocer: { present: ["conozco", "conocés", "conoces", "conoce", "conocemos", "conocen"], subjunctive: ["conozca", "conozcás", "conozcas", "conozca", "conozcamos", "conozcan"] },
  dar: { present: ["doy", "das", "das", "da", "damos", "dan"], preterite: ["di", "diste", "diste", "dio", "dimos", "dieron"], subjunctive: ["dé", "dés", "des", "dé", "demos", "den"] },
  ver: { present: ["veo", "ves", "ves", "ve", "vemos", "ven"], preterite: ["vi", "viste", "viste", "vio", "vimos", "vieron"], imperfect: ["veía", "veías", "veías", "veía", "veíamos", "veían"], subjunctive: ["vea", "veás", "veas", "vea", "veamos", "vean"] },
