  poner: { present: ["pongo", "ponés", "pones", "pone", "ponemos", "ponen"], preterite: ["puse", "pusiste", "pusiste", "puso", "pusimos", "pusieron"], futureStem: "pondr", subjunctive: ["ponga", "pongás", "pongas", "ponga", "pongamos", "pongan"] },
