const tenseNames = {
  present: "Present",
  preterite: "Preterite",
  imperfect: "Imperfect",
  future: "Future",
  conditional: "Conditional",
  subjunctive: "Present subjunctive"
};

function cleanInfinitive(inf) {
  return inf.replace(/se$/, "");
}

function verbEnding(inf) {
  const base = cleanInfinitive(inf);
  return base.slice(-2);
}

function stem(inf) {
  const base = cleanInfinitive(inf);
  return base.slice(0, -2);
}

function accentLastVowel(text) {
  const accents = {a:"á", e:"é", i:"í", o:"ó", u:"ú"};
  for (let i = text.length - 1; i >= 0; i--) {
    const ch = text[i].toLowerCase();
    if (accents[ch]) return text.slice(0, i) + accents[ch] + text.slice(i + 1);
  }
  return text;
}

function regularForms(inf, tense) {
  if (inf.includes(" ")) return ["—", "—", "—", "—", "—", "—"];
  const base = cleanInfinitive(inf);
  const end = verbEnding(inf);
  const st = stem(inf);
  const isReflexive = inf.endsWith("se");
  let forms;
  if (tense === "present") {
    if (end === "ar") forms = [st+"o", accentLastVowel(st+"as"), st+"as", st+"a", st+"amos", st+"an"];
    else if (end === "er") forms = [st+"o", accentLastVowel(st+"es"), st+"es", st+"e", st+"emos", st+"en"];
    else forms = [st+"o", accentLastVowel(st+"is"), st+"es", st+"e", st+"imos", st+"en"];
  } else if (tense === "preterite") {
    if (end === "ar") forms = [st+"é", st+"aste", st+"aste", st+"ó", st+"amos", st+"aron"];
    else forms = [st+"í", st+"iste", st+"iste", st+"ió", st+"imos", st+"ieron"];
  } else if (tense === "imperfect") {
    if (end === "ar") forms = [st+"aba", st+"abas", st+"abas", st+"aba", st+"ábamos", st+"aban"];
    else forms = [st+"ía", st+"ías", st+"ías", st+"ía", st+"íamos", st+"ían"];
  } else if (tense === "future") {
    forms = [base+"é", base+"ás", base+"ás", base+"á", base+"emos", base+"án"];
  } else if (tense === "conditional") {
    forms = [base+"ía", base+"ías", base+"ías", base+"ía", base+"íamos", base+"ían"];
  } else if (tense === "subjunctive") {
    if (end === "ar") forms = [st+"e", st+"és", st+"es", st+"e", st+"emos", st+"en"];
    else forms = [st+"a", st+"ás", st+"as", st+"a", st+"amos", st+"an"];
  }
  if (isReflexive && forms) {
    const refs = ["me ", "te ", "te ", "se ", "nos ", "se "];
    forms = forms.map((f, i) => refs[i] + f);
  }
  return forms || ["—", "—", "—", "—", "—", "—"];
}

function conjugate(inf, tense) {
  const base = cleanInfinitive(inf);
  const irr = irregulars[base];
  const isReflexive = inf.endsWith("se");
  let forms = null;
  if (irr) {
    if (irr[tense]) forms = irr[tense];
    else if ((tense === "future" || tense === "conditional") && irr.futureStem) {
      forms = tense === "future"
        ? ["é", "ás", "ás", "á", "emos", "án"].map(x => irr.futureStem + x)
        : ["ía", "ías", "ías", "ía", "íamos", "ían"].map(x => irr.futureStem + x);
    }
  }
  if (!forms) forms = regularForms(inf, tense);
  if (isReflexive && irr && !forms[0].startsWith("me ")) {
    const refs = ["me ", "te ", "te ", "se ", "nos ", "se "];
    forms = forms.map((f, i) => refs[i] + f);
  }
  return forms;
}

function el(id) { return document.getElementById(id); }
function norm(s) { return String(s || "").toLowerCase().normalize("NFD").replace(/[̀-ͯ]/g, ""); }
function hit(obj, q) { return norm(JSON.stringify(obj)).includes(norm(q)); }

function card(title, body, tag = "") {
  return `<article class="mini-card"><div class="mini-top"><h3>${title}</h3>${tag ? `<span class="tag">${tag}</span>` : ""}</div><p>${body}</p></article>`;
}

function renderCounts() {
  const vocabCount = STUDY_DATA.vocab.reduce((sum, group) => sum + group.words.length, 0);
  el("count-verbs").textContent = STUDY_DATA.verbs.length;
  el("count-adjectives").textContent = STUDY_DATA.adjectives.length;
  el("count-vocab").textContent = vocabCount;
  el("count-slang").textContent = STUDY_DATA.slang.length;
}

function renderGrammar() {
  const depthMap = { basic: 1, core: 2, advanced: 3 };
  const depth = Number(el("depthSlider").value);
  el("depthLabel").textContent = depth === 1 ? "Basics" : depth === 2 ? "Core" : "Full";
  el("grammarPanels").innerHTML = STUDY_DATA.grammar.map(group => {
    const items = group.items.filter(item => depthMap[item.level] <= depth);
    if (!items.length) return "";
    return `<details class="accordion" open><summary>${group.group}</summary>${items.map(item => `
      <div class="grammar-item"><h3>${item.title}</h3><p>${item.body}</p><span class="tag">${item.level}</span></div>
    `).join("")}</details>`;
  }).join("");
}

function renderVocab(topic = "all") {
  const groups = STUDY_DATA.vocab;
  el("topicButtons").innerHTML = `<button class="chip active" data-topic="all">All topics</button>` + groups.map(g => `<button class="chip" data-topic="${g.topic}">${g.icon} ${g.topic}</button>`).join("");
  document.querySelectorAll("#topicButtons .chip").forEach(btn => {
    btn.addEventListener("click", () => {
      document.querySelectorAll("#topicButtons .chip").forEach(b => b.classList.remove("active"));
      btn.classList.add("active");
      renderVocabCards(btn.dataset.topic);
    });
  });
  renderVocabCards(topic);
}

function renderVocabCards(topic = "all") {
  const selected = topic === "all" ? STUDY_DATA.vocab : STUDY_DATA.vocab.filter(g => g.topic === topic);
  el("vocabGrid").innerHTML = selected.map(group => `
    <section class="topic-card">
      <img class="topic-image" src="${group.image}" alt="${group.topic} visual" />
      <div class="topic-card-body">
        <h3>${group.icon} ${group.topic}</h3>
        <div class="word-list">${group.words.map(w => `<div class="word-row"><strong>${w[0]}</strong><span>${w[1]}</span><em>${w[2]}</em></div>`).join("")}</div>
      </div>
    </section>
  `).join("");
}

function renderVerbFilters() {
  const cats = [...new Set(STUDY_DATA.verbs.map(v => v.category))].sort();
  el("verbCategory").innerHTML = `<option value="all">All categories</option>` + cats.map(c => `<option value="${c}">${c}</option>`).join("");
}

function renderVerbList() {
  const q = el("verbSearch").value;
  const cat = el("verbCategory").value;
  const verbs = STUDY_DATA.verbs.filter(v => (cat === "all" || v.category === cat) && hit(v, q));
  el("verbList").innerHTML = verbs.map(v => `<button class="verb-pill" data-verb="${v.infinitive}"><strong>${v.infinitive}</strong><span>${v.meaning}</span></button>`).join("") || `<p class="muted">No verbs found.</p>`;
  document.querySelectorAll(".verb-pill").forEach(btn => btn.addEventListener("click", () => showVerb(btn.dataset.verb)));
}

function showVerb(inf) {
  const v = STUDY_DATA.verbs.find(x => x.infinitive === inf);
  const tenses = ["present", "preterite", "imperfect", "future", "conditional", "subjunctive"];
  el("verbDetail").innerHTML = `
    <div class="verb-heading"><div><h3>${v.infinitive}</h3><p>${v.meaning}</p></div><span class="tag">${v.pattern}</span></div>
    <p class="example"><strong>Example:</strong> ${v.example}</p>
    <p class="note"><strong>Note:</strong> Regular tables are generated automatically. Very irregular verbs and the most important forms are manually corrected. Stem-changing verbs are marked so you know to double-check the pattern when you study them deeply.</p>
    ${tenses.map(t => `
      <details class="conj" ${t === "present" ? "open" : ""}>
        <summary>${tenseNames[t]}</summary>
        <table class="conj-table"><tbody>
          ${conjugate(v.infinitive, t).map((form, i) => `<tr><th>${pronouns[i]}</th><td>${form}</td></tr>`).join("")}
        </tbody></table>
      </details>`).join("")}
  `;
}

function renderAdjectives() {
  const cats = [...new Set(STUDY_DATA.adjectives.map(a => a.category))].sort();
  el("adjectiveCategory").innerHTML = `<option value="all">All adjective groups</option>` + cats.map(c => `<option value="${c}">${c}</option>`).join("");
  renderAdjectiveGrid();
}

function renderAdjectiveGrid() {
  const q = el("adjectiveSearch").value;
  const cat = el("adjectiveCategory").value;
  const items = STUDY_DATA.adjectives.filter(a => (cat === "all" || a.category === cat) && hit(a, q));
  el("adjectiveGrid").innerHTML = items.map(a => card(a.word, `<strong>${a.meaning}</strong><br>${a.example}`, a.category)).join("") || `<p class="muted">No adjectives found.</p>`;
}

function renderAdverbs() {
  el("adverbGrid").innerHTML = STUDY_DATA.adverbs.map(a => card(a.word, `<strong>${a.meaning}</strong><br>${a.example}<br><span class="note-line">${a.note}</span>`)).join("");
}

function renderSlang() {
  el("slangGrid").innerHTML = STUDY_DATA.slang.map(s => card(s.term, `<strong>${s.meaning}</strong><br>${s.example}<br><span class="note-line">${s.tone}</span>`, s.region)).join("");
}

function renderPractice() {
  el("practiceList").innerHTML = STUDY_DATA.practicePrompts.map((p, i) => `<article class="practice-card"><span>${String(i + 1).padStart(2, "0")}</span><p>${p}</p></article>`).join("");
}

function renderSearch() {
  const q = el("searchInput").value.trim();
  const type = el("searchType").value;
  if (!q) {
    el("searchResults").innerHTML = `<p class="muted">Start typing to search the whole reference.</p>`;
    return;
  }
  let results = [];
  if (type === "all" || type === "verb") results.push(...STUDY_DATA.verbs.filter(x => hit(x, q)).map(x => ["Verb", x.infinitive, `${x.meaning} — ${x.example}`]));
  if (type === "all" || type === "adjective") results.push(...STUDY_DATA.adjectives.filter(x => hit(x, q)).map(x => ["Adjective", x.word, `${x.meaning} — ${x.example}`]));
  if (type === "all" || type === "adverb") results.push(...STUDY_DATA.adverbs.filter(x => hit(x, q)).map(x => ["Adverb", x.word, `${x.meaning} — ${x.example}`]));
  if (type === "all" || type === "slang") results.push(...STUDY_DATA.slang.filter(x => hit(x, q)).map(x => ["Slang", x.term, `${x.meaning} — ${x.example}`]));
  if (type === "all" || type === "vocab") {
    STUDY_DATA.vocab.forEach(group => group.words.forEach(w => { if (hit({ group: group.topic, word: w }, q)) results.push(["Vocabulary", w[0], `${w[1]} — ${w[2]}`]); }));
  }
  if (type === "all" || type === "grammar") {
    STUDY_DATA.grammar.forEach(group => group.items.forEach(item => { if (hit(item, q)) results.push(["Grammar", item.title, item.body]); }));
  }
  el("searchResults").innerHTML = results.slice(0, 48).map(r => card(r[1], r[2], r[0])).join("") || `<p class="muted">No results yet. Try a smaller word or English meaning.</p>`;
}



