// Override image-heavy vocabulary cards: this version is text-first.
function renderVocabCards(topic = "all") {
  const selected = topic === "all" ? STUDY_DATA.vocab : STUDY_DATA.vocab.filter(g => g.topic === topic);
  el("vocabGrid").innerHTML = selected.map(group => `
    <section class="topic-card no-image">
      <div class="topic-card-body">
        <h3>${group.icon || "✦"} ${group.topic}</h3>
        <div class="word-list">${group.words.map(w => `<div class="word-row"><strong>${w[0]}</strong><span>${w[1]}</span><em>${w[2]}</em></div>`).join("")}</div>
      </div>
    </section>
  `).join("");
}

function storyTokenize(text) {
  const glossary = STUDY_DATA.storyGlossary;
  const parts = text.split(/(\s+|[.,;:¿?¡!—“”"()]+)/u);
  return parts.map(part => {
    const key = norm(part);
    const raw = part.trim();
    if (!raw || /^\s+$/.test(part) || /^[.,;:¿?¡!—“”"()]+$/.test(part)) return part;
    const phrase = glossary[raw.toLowerCase()] || glossary[key] || null;
    return `<button class="story-word" data-word="${raw.replace(/"/g, '&quot;')}" data-note="${(phrase || 'No custom note yet. Add this word to STUDY_DATA.storyGlossary if you want a fuller explanation.').replace(/"/g, '&quot;')}">${part}</button>`;
  }).join("");
}

function renderStories() {
  const target = el("storiesPanel");
  if (!target) return;
  target.innerHTML = STUDY_DATA.stories.map((story, idx) => `
    <details class="story-card" ${idx === 0 ? "open" : ""}>
      <summary><span>${story.level}</span> ${story.title}</summary>
      <p class="story-summary">${story.summary}</p>
      <div class="story-body">${story.paragraphs.map(p => `<p>${storyTokenize(p)}</p>`).join("")}</div>
    </details>
  `).join("");
}

function bindStoryClicks() {
  document.addEventListener("click", (event) => {
    const btn = event.target.closest(".story-word");
    if (!btn) {
      if (!event.target.closest(".word-popover")) document.querySelectorAll(".word-popover").forEach(x => x.remove());
      return;
    }
    document.querySelectorAll(".story-word.active").forEach(x => x.classList.remove("active"));
    document.querySelectorAll(".word-popover").forEach(x => x.remove());
    btn.classList.add("active");
    const pop = document.createElement("span");
    pop.className = "word-popover";
    pop.innerHTML = `<strong>${btn.dataset.word}</strong><small>${btn.dataset.note}</small>`;
    btn.insertAdjacentElement("afterend", pop);
  });
}

document.addEventListener("DOMContentLoaded", () => {
  renderCounts();
  renderGrammar();
  renderVocab();
  renderVerbFilters();
  renderVerbList();
  showVerb("ser");
  renderAdjectives();
  renderAdverbs();
  renderSlang();
  renderPractice();
  renderStories();
  bindStoryClicks();
  renderSearch();

  el("depthSlider").addEventListener("input", renderGrammar);
  el("verbSearch").addEventListener("input", renderVerbList);
  el("verbCategory").addEventListener("change", renderVerbList);
  el("adjectiveSearch").addEventListener("input", renderAdjectiveGrid);
  el("adjectiveCategory").addEventListener("change", renderAdjectiveGrid);
  el("searchInput").addEventListener("input", renderSearch);
  el("searchType").addEventListener("change", renderSearch);
});



