function storyNoteKey(value) {
  return String(value || "")
    .trim()
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[^a-zñü]/g, "");
}

function escapeStoryHtml(value) {
  return String(value ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#039;");
}

function encodeStoryNote(note) {
  return encodeURIComponent(JSON.stringify(note));
}

function decodeStoryNote(encoded) {
  try {
    return JSON.parse(decodeURIComponent(encoded));
  } catch (error) {
    return {
      translation: "open note",
      pos: "note",
      root: "",
      form: "",
      note: "This note could not be decoded."
    };
  }
}

function findStudyEntryForStoryWord(word) {
  const key = storyNoteKey(word);
  if (!key) return null;

  for (const verb of STUDY_DATA.verbs || []) {
    if (storyNoteKey(verb.infinitive) === key) {
      return {
        translation: verb.meaning || "verb",
        pos: "verb",
        root: verb.infinitive,
        form: "infinitive",
        note: verb.example ? `Example from verb bank: ${verb.example}` : "Infinitive/root form."
      };
    }
  }

  for (const adjective of STUDY_DATA.adjectives || []) {
    const raw = String(adjective.word || "");
    const baseRaw = raw.replace("/a", "").replace("/os", "").replace("/as", "");
    const base = storyNoteKey(baseRaw);
    const possible = new Set([base, storyNoteKey(raw), base + "a", base + "o", base + "os", base + "as", base + "es"]);
    if (possible.has(key)) {
      return {
        translation: adjective.meaning || "adjective",
        pos: "adjective",
        root: adjective.word,
        form: "agreement form",
        note: adjective.example ? `Example: ${adjective.example}` : "Adjectives must agree with the noun they describe."
      };
    }
  }

  for (const adverb of STUDY_DATA.adverbs || []) {
    if (storyNoteKey(adverb.word) === key) {
      return {
        translation: adverb.meaning || "adverb",
        pos: "adverb",
        root: adverb.word,
        form: "adverb / phrase",
        note: adverb.note || adverb.example || "Small words like this carry a lot of meaning in real sentences."
      };
    }
  }

  for (const group of STUDY_DATA.vocab || []) {
    for (const row of group.words || []) {
      const spanish = String(row[0] || "");
      const stripped = spanish.replace(/^(el|la|los|las|un|una|unos|unas)\s+/i, "");
      const candidates = [spanish, stripped, stripped.replace(/s$/i, ""), stripped.replace(/es$/i, "")].map(storyNoteKey);
      if (candidates.includes(key)) {
        return {
          translation: row[1] || "vocabulary word",
          pos: row[3] || "vocabulary",
          root: stripped,
          form: row[3] || "dictionary form",
          note: row[2] ? `Example: ${row[2]}` : `Topic: ${group.topic}`
        };
      }
    }
  }

  return null;
}

function getStoryNote(word) {
  const key = storyNoteKey(word);
  const custom = STUDY_DATA.storyWordNotes && STUDY_DATA.storyWordNotes[key];
  if (custom) return custom;

  const fromStudyData = findStudyEntryForStoryWord(word);
  if (fromStudyData) return fromStudyData;

  const legacy = (STUDY_DATA.storyGlossary && (STUDY_DATA.storyGlossary[word.toLowerCase()] || STUDY_DATA.storyGlossary[key])) || "";
  if (legacy) {
    const parts = String(legacy).split("—");
    return {
      translation: (parts[0] || legacy).trim(),
      pos: "reading note",
      root: "",
      form: "",
      note: (parts.slice(1).join("—") || "Legacy story note.").trim()
    };
  }

  return {
    translation: word,
    pos: "context word",
    root: "",
    form: "unlisted form",
    note: "This word is clickable, but it is not in the hand-built notes yet. Use the surrounding sentence for context and add it to STUDY_DATA.storyWordNotes if you want a permanent custom note."
  };
}

function storyTokenize(text) {
  const parts = String(text).split(/(\s+|[.,;:¿?¡!—“”"()]+)/u);
  return parts.map(part => {
    const raw = part.trim();
    if (!raw || /^\s+$/.test(part) || /^[.,;:¿?¡!—“”"()]+$/.test(part)) return part;
    const note = getStoryNote(raw);
    const encoded = encodeStoryNote(note);
    return `<button class="story-word" data-word="${escapeStoryHtml(raw)}" data-note="${encoded}">${escapeStoryHtml(part)}</button>`;
  }).join("");
}

function renderStories() {
  const target = el("storiesPanel");
  if (!target) return;
  target.innerHTML = STUDY_DATA.stories.map((story, idx) => `
    <details class="story-card" ${idx === 0 ? "open" : ""}>
      <summary><span>${story.level}</span> ${escapeStoryHtml(story.title)}</summary>
      <p class="story-summary">${escapeStoryHtml(story.summary)}</p>
      <p class="story-note-hint">Click a word to see English, word type, root form, tense/form, and a short usage note.</p>
      <div class="story-body">${story.paragraphs.map(p => `<p>${storyTokenize(p)}</p>`).join("")}</div>
    </details>
  `).join("");
}

function bindStoryClicks() {
  document.addEventListener("click", (event) => {
    const btn = event.target.closest(".story-word");
    if (!btn) {
      if (!event.target.closest(".word-popover")) {
        document.querySelectorAll(".word-popover").forEach(x => x.remove());
        document.querySelectorAll(".story-word.active").forEach(x => x.classList.remove("active"));
      }
      return;
    }

    const alreadyActive = btn.classList.contains("active");
    document.querySelectorAll(".story-word.active").forEach(x => x.classList.remove("active"));
    document.querySelectorAll(".word-popover").forEach(x => x.remove());
    if (alreadyActive) return;

    btn.classList.add("active");
    const note = decodeStoryNote(btn.dataset.note);
    const pop = document.createElement("span");
    pop.className = "word-popover rich-word-popover";
    pop.innerHTML = `
      <strong class="popover-word">${escapeStoryHtml(btn.dataset.word)}</strong>
      <dl>
        <div><dt>English</dt><dd>${escapeStoryHtml(note.translation || "")}</dd></div>
        <div><dt>Type</dt><dd>${escapeStoryHtml(note.pos || "")}</dd></div>
        ${note.root ? `<div><dt>Root</dt><dd>${escapeStoryHtml(note.root)}</dd></div>` : ""}
        ${note.form ? `<div><dt>Form</dt><dd>${escapeStoryHtml(note.form)}</dd></div>` : ""}
      </dl>
      ${note.note ? `<small>${escapeStoryHtml(note.note)}</small>` : ""}
    `;
    btn.insertAdjacentElement("afterend", pop);
  });
}


