function addUniqueStudyItems(target, items, key) {
  const seen = new Set(target.map(item => norm(item[key])));
  items.forEach(item => {
    const id = norm(item[key]);
    if (!seen.has(id)) {
      target.push(item);
      seen.add(id);
    }
  });
}

function uniqueStudyItems(items, key) {
  const seen = new Set();
  return items.filter(item => {
    const id = norm(item[key]);
    if (seen.has(id)) return false;
    seen.add(id);
    return true;
  });
}

addUniqueStudyItems(STUDY_DATA.verbs, FLUENCY_VERB_EXPANSION, "infinitive");
addUniqueStudyItems(STUDY_DATA.adjectives, FLUENCY_ADJECTIVE_EXPANSION, "word");

STUDY_DATA.verbs = uniqueStudyItems(STUDY_DATA.verbs, "infinitive");
STUDY_DATA.adjectives = uniqueStudyItems(STUDY_DATA.adjectives, "word");

